window.AUTH=window.AUTH||{};window.AUTH["24-724"]={"d":"24-724","id":"2025/24-724","n":"Hain Celestial Group, Inc. v. Palmquist","briefs":[{"k":"petitioner","label":"Brief of petitioners The Hain Celestial Group, Inc., Whole Foods Market, Inc.","date":"2025-06-27","url":"https://www.supremecourt.gov/DocketPDF/24/24-724/364036/20250627145559504_24-724%20Brief%20of%20Petitioners.pdf","side":"pet","n":35},{"k":"respondent","label":"Brief of respondents Sarah Palmquist, Individually and as Next Friend of E.P., a Minor, et al.","date":"2025-08-11","url":"https://www.supremecourt.gov/DocketPDF/24/24-724/369407/20250811163207161_resp.%20merits%20brief%20-%20Hain%20Celestial%20v.%20Palmquist%20-%20No.%2024-724.pdf","side":"res","n":67},{"k":"reply","label":"Reply of petitioners The Hain Celestial Group, Inc., et al.","date":"2025-09-10","url":"https://www.supremecourt.gov/DocketPDF/24/24-724/374297/20250910160916509_24-724%20Reply%20Brief.pdf","side":"pet","n":23}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/607us2r14_1a72.pdf","tr":true,"items":[{"t":"case","label":"Amstadt v. U.S. Brass Corp.","cite":"919 S.W.2d 644","y":1996,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.2d/919/644/","by":{"0":"27"}},{"t":"case","label":"Anderson v. Watt","cite":"138 U.S. 694","y":1891,"id":"scdb/1890-148","sc":1,"sum":"Since the passage of tbe act of March 3, 1875, 18 Stat. 470, if it appear from the pleadings and proofs, taken together, that the defendants are citizens of the United States, and reside, in the sense of having their permanent domicil, in the State of which the complainants are citizens, (or that each of the indispensable adverse parties is not competent to sue or. liable to be sued therein,) the Circuit Court …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"13","1":"3, 32"}},{"t":"case","label":"Caterpillar, Inc. v. Lewis","cite":"519 U.S. 61","y":1996,"id":"1996/95-1263","sc":1,"op":6,"sum":"A failure to remand a case improperly removed is not fatal to federal adjudication of the case so long as federal jurisdictional requirements are met at the time judgment is entered. When a diversity case has been tried in federal court under state rules of decision, the importance of finality, efficiency and economy in judicial determinations becomes decisive.","sumSrc":"Oyez","by":{"0":"12–16, 18, 19, 32","1":"4, 10, 12, 15, 18, 20-22, 24-33, 35-36, 40, 42","2":"6, 12, 14"}},{"t":"case","label":"Chesapeake & O. R. Co. v. Cockrell","cite":"232 U.S. 146","y":1914,"id":"scdb/1913-261","sc":1,"sum":"As the right to remove a cause from a state to a Federal court exists only in enumerated classes of cases, the petition must set forth the. particular facts which bring the case within one of such classes; general allegations and mere legal conclusions are not sufficient.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"4","1":"16"}},{"t":"case","label":"Curley v. Brignoli, Curley & Roberts Assocs.","cite":"915 F.2d 81","y":1990,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/915/81/","by":{"0":"31"}},{"t":"case","label":"Erie R. Co. v. Tompkins","cite":"304 U.S. 64","y":1938,"id":"1900-1940/304us64","sc":1,"ar":1,"sum":"A case in which the Court overturned its prior decision in Swift v. Tyson and held that federal courts exercising diversity jurisdiction cannot create their own common law for issues that properly fall within state law.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Gorfinkle v. U.S. Airways, Inc.","cite":"431 F.3d 19","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/431/19/","op":1,"by":{"0":"30, 31","1":"43","2":"19"}},{"t":"case","label":"Grice v. CVR Energy, Inc.","cite":"921 F.3d 966","y":2019,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/921/966/","by":{"0":"31","1":"43"}},{"t":"case","label":"Grupo Dataflux v. Atlas Glob. Grp., L.P.","cite":"541 U.S. 567","y":2004,"id":"2003/02-1689","sc":1,"op":2,"sum":"In a 5-to-4 decision written by Justice Antonin Scalia, the Court ruled that allowing diversity jurisdiction to change after a case is filed would create uncertainty and expensive litigation that dealt with jurisdiction rather than the merits of the case. \"Uncertainty regarding the question of jurisdiction is particularly undesirable, and collateral litigation on the point particularly wasteful,\" wrote Justice Scalia. \"The stability provided by our time tested rule (of requiring diversity at the time of filing) weighs heavily against the approval of any new deviation.\".","sumSrc":"Oyez","by":{"0":"13, 14, 19, 21, 23","1":"3, 14, 19, 30-35","2":"8, 10, 16, 17"}},{"t":"case","label":"Hanna v. Plumer","cite":"380 U.S. 460","y":1965,"id":"1964/171","sc":1,"sum":"The Court ruled for Hanna. To raise the Erie doctrine, the Court reasoned, the effect of a procedural rule on the outcome of a case must abridge, enlarge, or modify the substantive law. There was no change to a substantive right here because the plaintiff simply could refile the case or serve the defendant personally.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Helena Chem. Co. v. Cox","cite":"664 S.W.3d 66","y":2023,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.3d/664/66/","by":{"0":"31"}},{"t":"case","label":"Highland Cap. Mgmt. L.P. v. Schneider","cite":"198 F. App’x 41","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/198/41/","by":{"0":"30","1":"43","2":"19"}},{"t":"case","label":"Ingram v. CSX Transp., Inc.","cite":"146 F.3d 858","y":1998,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/146/858/","by":{"0":"30, 31","1":"43","2":"19"}},{"t":"case","label":"Lakes of Rosehill Homeowners Ass’n, Inc. v. Jones","cite":"552 S.W.3d 414","y":2018,"court":"Tex. App.","url":"https://www.courtlistener.com/c/S.W.3d/552/414/","by":{"0":"27","1":"46"}},{"t":"case","label":"Martinez v. Duke Energy Corp.","cite":"130 F. App’x 629","y":2005,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/130/629/","by":{"0":"31","1":"43"}},{"t":"case","label":"Mullaney v. Anderson","cite":"342 U.S. 415","y":1952,"id":"scdb/1951-045","sc":1,"sum":"In the special circumstances of this case, the motion is granted. (See Rule 21 of the Federal Rules of Civil P~ocedure.) Pp. 416-417. 191 F. 2d 123, affirmed. In a suit to enjoin enforcement, the District Court for the Territory of Alaska upheld a tax statute of Alaska. 91 F. Supp. 907. The Court of Appeals reversed. 191 F. 2d 123. This Court granted certiorari. 342 U. S. 865. Affirmed, -p. 420. J. Gerald Williams, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Newman Green, Inc. v. Alfonzo-Larrain","cite":"1987 WL 5232","y":1987,"court":"N.D. Ill. Jan. 7","op":4,"ar":4,"by":{"0":"27"}},{"t":"case","label":"Newman-Green, Inc. v. Alfonzo-Larrain","cite":"832 F.2d 417","y":1987,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/832/417/","sum":"Noting that lost judgment is not “the sense of prejudice that matters” under Rule 21.","sumSrc":"brief:0","by":{"0":"29"}},{"t":"case","label":"Newman-Green, Inc. v. Alfonzo-Larrain","cite":"854 F.2d 916","y":1988,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/854/916/","by":{"0":"27"}},{"t":"case","label":"Newman-Green, Inc. v. Alfonzo-Larrain","cite":"490 U.S. 826","y":1989,"id":"1988/88-774","sc":1,"op":2,"sum":"A court of appeals has the authority to grant a motion to dismiss a dispensable nondiverse party and need not remand the case to the district court for dismissal in that court's discretion.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 22–24, 26–29","1":"38-45, 47-48","2":"1, 6, 14, 17, 18, 19, 20"}},{"t":"case","label":"Provident Tradesmens Bank & Tr. Co. v. Patterson","cite":"390 U.S. 102","y":1968,"id":"1967/28","sc":1,"sum":"An automobile owned by Dutcher, driven by Cionci, to whom Dutcher had given the keys, in which Lynch and Harris were passengers, collided with a truck driven by Smith. Cionci,. Lynch and Smith were killed and Harris was injured. The administrator of Lynch's estate, the petitioner here, sued Cionci's estate in a diversity action which was settled for $50,000, which was not paid as Cionci's estate was penniless. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29, 32"}},{"t":"case","label":"Royal Canin U.S.A., Inc. v. Wullschleger","cite":"604 U.S. 22","y":2025,"id":"2024/23-677","sc":1,"op":2,"ar":5,"sum":"When a plaintiff amends her complaint to delete the federal-law claims that enabled removal to federal court, leaving only state-law claims behind, the federal court loses supplemental jurisdiction over the state claims, and the case must be remanded to state court.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"12, 13, 15","1":"3, 14, 18, 21, 26, 33, 37, 44-45"}},{"t":"case","label":"St. Paul Mercury Indem. Co. v. Red Cab Co.","cite":"303 U.S. 283","y":1938,"id":"scdb/1937-104","sc":1,"sum":"1. There is a strong presumption that the plaintiff in a state court has not claimed a large amount in order to confer jurisdiction by removal on a federal court, and that the parties have not colluded to that end.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"Temple v. Synthes Corp.","cite":"498 U.S. 5","y":1990,"id":"1990/90-295","sc":1,"sum":"The doctor and the hospital are potential joint tortfeasors and, therefore, are not indispensable parties under Rule 19(b). It is not necessary for all joint tortfeasors to be named as defendants in a single lawsuit. See, e. g., Lawlor v. National Screen Service Corp., 349 U. S. 322, 329-330. Nothing in the 1966 revision of Rule 19 changed that principle, see Provident Tradesrnens Bank & Trust Co. v. Patterson, 390 …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26","1":"46"}},{"t":"case","label":"Travis v. Irby","cite":"326 F.3d 644","y":2003,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/326/644/","by":{"0":"4"}},{"t":"case","label":"Weber v. GE Grp. Life Assur. Co.","cite":"541 F.3d 1002","y":2008,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/541/1002/","by":{"0":"29","1":"43"}},{"t":"const","label":"Article III, Section 2","clauses":[["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"]],"text":"The judicial Power shall extend to all Cases, in Law and Equity, arising under this Constitution, the Laws of the United States, and Treaties made, or which shall be made, under their Authority;—to all Cases affecting Ambassadors, other public Ministers and Consuls;—to all Cases of admiralty and maritime Jurisdiction;—to Controversies to which the United States shall be a Party;—to Controversies between two or more States;— between a State and Citizens of another State,—between Citizens of different States,—between Citizens of the same State claiming Lands under Grants of different States, and between a State, or the Citizens thereof, and foreign States, Citizens or Subjects. In all Cases affecting Ambassadors, other public Ministers and Consuls, and those in which a State shall be Party, the supreme Court shall have original Jurisdiction. In all the other Cases before mentioned, the supreme Court shall have appellate Jurisdiction, both as to Law and Fact, with such Exceptions, and under such Regulations as the Congress shall make. The Trial of all Crimes, except in Cases of Impeachment, shall be by Jury; and such Trial shall be held in the State where the said Crimes shall have been committed; but when not committed within any State, the Trial shall be at such Place or Places as the Congress may by Law have directed.","by":{"0":"1, 11"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1332","url":"https://www.law.cornell.edu/uscode/text/28/1332","subs":["(a)","(a)(1)"],"stext":{"head":"§1332. Diversity of citizenship; amount in controversy; costs","paras":[[0,"(a) The district courts shall have original jurisdiction of all civil actions where the matter in controversy exceeds the sum or value of $75,000, exclusive of interest and costs, and is between—"],[1,"(1) citizens of different States;"],[1,"(2) citizens of a State and citizens or subjects of a foreign state, except that the district courts shall not have original jurisdiction under this subsection of an action between citizens of a State and citizens or subjects of a foreign state who are lawfully admitted for permanent residence in the United States and are domiciled in the same State;"],[1,"(3) citizens of different States and in which citizens or subjects of a foreign state are additional parties; and"],[1,"(4) a foreign state, defined in section 1603(a) of this title, as plaintiff and citizens of a State or of different States."],[0,"(b) Except when express provision therefor is otherwise made in a statute of the United States, where the plaintiff who files the case originally in the Federal courts is finally adjudged to be entitled to recover less than the sum or value of $75,000, computed without regard to any setoff or counterclaim to which the defendant may be adjudged to be entitled, and exclusive of interest and costs, the district court may deny costs to the plaintiff and, in addition, may impose costs on the plaintiff."],[0,"(c) For the purposes of this section and section 1441 of this title—"],[1,"(1) a corporation shall be deemed to be a citizen of every State and foreign state by which it has been incorporated and of the State or foreign state where it has its principal place of business, except that in any direct action against the insurer of a policy or contract of liability insurance, whether incorporated or unincorporated, to which action the insured is not joined as a party-defendant, such insurer shall be deemed a citizen of—"],[2,"(A) every State and foreign state of which the insured is a citizen;"],[2,"(B) every State and foreign state by which the insurer has been incorporated; and"],[2,"(C) the State or foreign state where the insurer has its principal place of business; and"],[1,"(2) the legal representative of the estate of a decedent shall be deemed to be a citizen only of the same State as the decedent, and the legal representative of an infant or incompetent shall be deemed to be a citizen only of the same State as the infant or incompetent."],[0,"(d)(1) In this subsection—"],[1,"(A) the term \"class\" means all of the class members in a class action;"],[1,"(B) the term \"class action\" means any civil action filed under rule 23 of the Federal Rules of Civil Procedure or similar State statute or rule of judicial procedure authorizing an action to be brought by 1 or more representative persons as a class action;"],[1,"(C) the term \"class certification order\" means an order issued by a court approving the treatment of some or all aspects of a civil action as a class action; and"],[1,"(D) the term \"class members\" means the persons (named or unnamed) who fall within the definition of the proposed or certified class in a class action."],[0,"(2) The district courts shall have original jurisdiction of any civil action in which the matter in controversy exceeds the sum or value of $5,000,000, exclusive of interest and costs, and is a class action in which—"],[1,"(A) any member of a class of plaintiffs is a citizen of a State different from any defendant;"],[1,"(B) any member of a class of plaintiffs is a foreign state or a citizen or subject of a foreign state and any defendant is a citizen of a State; or"],[1,"(C) any member of a class of plaintiffs is a citizen of a State and any defendant is a foreign state or a citizen or subject of a foreign state."],[0,"(3) A district court may, in the interests of justice and looking at the totality of the circumstances, decline to exercise jurisdiction under paragraph (2) over a class action in which greater than one-third but less than two-thirds of the members of all proposed plaintiff classes in the aggregate and the primary defendants are citizens of the State in which the action was originally filed based on consideration of—"],[1,"(A) whether the claims asserted involve matters of national or interstate interest;"],[1,"(B) whether the claims asserted will be governed by laws of the State in which the action was originally filed or by the laws of other States;"],[1,"(C) whether the class action has been pleaded in a manner that seeks to avoid Federal jurisdiction;"],[1,"(D) whether the action was brought in a forum with a distinct nexus with the class members, the alleged harm, or the defendants;"],[1,"(E) whether the number of citizens of the State in which the action was originally filed in all proposed plaintiff classes in the aggregate is substantially larger than the number of citizens from any other State, and the citizenship of the other members of the proposed class is dispersed among a substantial number of States; and"],[1,"(F) whether, during the 3-year period preceding the filing of that class action, 1 or more other class actions asserting the same or similar claims on behalf of the same or other persons have been filed."],[0,"(4) A district court shall decline to exercise jurisdiction under paragraph (2)—"],[1,"(A)(i) over a class action in which—"],[2,"(I) greater than two-thirds of the members of all proposed plaintiff classes in the aggregate are citizens of the State in which the action was originally filed;"],[2,"(II) at least 1 defendant is a defendant—"],[3,"(aa) from whom significant relief is sought by members of the plaintiff class;"],[3,"(bb) whose alleged conduct forms a significant basis for the claims asserted by the proposed plaintiff class; and"],[3,"(cc) who is a citizen of the State in which the action was originally filed; and"],[2,"(III) principal injuries resulting from the alleged conduct or any related conduct of each defendant were incurred in the State in which the action was originally filed; and"],[1,"(ii) during the 3-year period preceding the filing of that class action, no other class action has been filed asserting the same or similar factual allegations against any of the defendants on behalf of the same or other persons; or"],[1,"(B) two-thirds or more of the members of all proposed plaintiff classes in the aggregate, and the primary defendants, are citizens of the State in which the action was originally filed."],[0,"(5) Paragraphs (2) through (4) shall not apply to any class action in which—"],[1,"(A) the primary defendants are States, State officials, or other governmental entities against whom the district court may be foreclosed from ordering relief; or"],[1,"(B) the number of members of all proposed plaintiff classes in the aggregate is less than 100."],[0,"(6) In any class action, the claims of the individual class members shall be aggregated to determine whether the matter in controversy exceeds the sum or value of $5,000,000, exclusive of interest and costs."],[0,"(7) Citizenship of the members of the proposed plaintiff classes shall be determined for purposes of paragraphs (2) through (6) as of the date of filing of the complaint or amended complaint, or, if the case stated by the initial pleading is not subject to Federal jurisdiction, as of the date of service by plaintiffs of an amended pleading, motion, or other paper, indicating the existence of Federal jurisdiction."],[0,"(8) This subsection shall apply to any class action before or after the entry of a class certification order by the court with respect to that action."],[0,"(9) Paragraph (2) shall not apply to any class action that solely involves a claim—"],[1,"(A) concerning a covered security as defined under 16(f)(3) 1 of the Securities Act of 1933 (15 U.S.C. 78p(f)(3) 2) and section 28(f)(5)(E) of the Securities Exchange Act of 1934 (15 U.S.C. 78bb(f)(5)(E));"],[1,"(B) that relates to the internal affairs or governance of a corporation or other form of business enterprise and that arises under or by virtue of the laws of the State in which such corporation or business enterprise is incorporated or organized; or"],[1,"(C) that relates to the rights, duties (including fiduciary duties), and obligations relating to or created by or pursuant to any security (as defined under section 2(a)(1) of the Securities Act of 1933 (15 U.S.C. 77b(a)(1)) and the regulations issued thereunder)."],[0,"(10) For purposes of this subsection and section 1453, an unincorporated association shall be deemed to be a citizen of the State where it has its principal place of business and the State under whose laws it is organized."],[0,"(11)(A) For purposes of this subsection and section 1453, a mass action shall be deemed to be a class action removable under paragraphs (2) through (10) if it otherwise meets the provisions of those paragraphs."],[0,"(B)(i) As used in subparagraph (A), the term \"mass action\" means any civil action (except a civil action within the scope of section 1711(2)) in which monetary relief claims of 100 or more persons are proposed to be tried jointly on the ground that the plaintiffs' claims involve common questions of law or fact, except that jurisdiction shall exist only over those plaintiffs whose claims in a mass action satisfy the jurisdictional amount requirements under subsection (a)."],[0,"(ii) As used in subparagraph (A), the term \"mass action\" shall not include any civil action in which—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1332?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1332. Diversity of citizenship; amount in controversy; costs","tname":"Judiciary and Judicial Procedure","by":{"0":"2, 4, 12, 18","1":"4, 15"}},{"t":"usc","label":"28 U.S.C. § 1441","url":"https://www.law.cornell.edu/uscode/text/28/1441","subs":["(a)"],"stext":{"head":"§1441. Removal of civil actions","paras":[[0,"(a) Generally.—Except as otherwise expressly provided by Act of Congress, any civil action brought in a State court of which the district courts of the United States have original jurisdiction, may be removed by the defendant or the defendants, to the district court of the United States for the district and division embracing the place where such action is pending."],[0,"(b) Removal Based on Diversity of Citizenship.—(1) In determining whether a civil action is removable on the basis of the jurisdiction under section 1332(a) of this title, the citizenship of defendants sued under fictitious names shall be disregarded."],[0,"(2) A civil action otherwise removable solely on the basis of the jurisdiction under section 1332(a) of this title may not be removed if any of the parties in interest properly joined and served as defendants is a citizen of the State in which such action is brought."],[0,"(c) Joinder of Federal Law Claims and State Law Claims.—(1) If a civil action includes—"],[1,"(A) a claim arising under the Constitution, laws, or treaties of the United States (within the meaning of section 1331 of this title), and"],[1,"(B) a claim not within the original or supplemental jurisdiction of the district court or a claim that has been made nonremovable by statute,"],[0,"the entire action may be removed if the action would be removable without the inclusion of the claim described in subparagraph (B)."],[0,"(2) Upon removal of an action described in paragraph (1), the district court shall sever from the action all claims described in paragraph (1)(B) and shall remand the severed claims to the State court from which the action was removed. Only defendants against whom a claim described in paragraph (1)(A) has been asserted are required to join in or consent to the removal under paragraph (1)."],[0,"(d) Actions Against Foreign States.—Any civil action brought in a State court against a foreign state as defined in section 1603(a) of this title may be removed by the foreign state to the district court of the United States for the district and division embracing the place where such action is pending. Upon removal the action shall be tried by the court without jury. Where removal is based upon this subsection, the time limitations of section 1446(b) of this chapter may be enlarged at any time for cause shown."],[0,"(e) Multiparty, Multiforum Jurisdiction.—(1) Notwithstanding the provisions of subsection (b) of this section, a defendant in a civil action in a State court may remove the action to the district court of the United States for the district and division embracing the place where the action is pending if—"],[1,"(A) the action could have been brought in a United States district court under section 1369 of this title; or"],[1,"(B) the defendant is a party to an action which is or could have been brought, in whole or in part, under section 1369 in a United States district court and arises from the same accident as the action in State court, even if the action to be removed could not have been brought in a district court as an original matter."],[0,"The removal of an action under this subsection shall be made in accordance with section 1446 of this title, except that a notice of removal may also be filed before trial of the action in State court within 30 days after the date on which the defendant first becomes a party to an action under section 1369 in a United States district court that arises from the same accident as the action in State court, or at a later time with leave of the district court."],[0,"(2) Whenever an action is removed under this subsection and the district court to which it is removed or transferred under section 1407(j) 1 has made a liability determination requiring further proceedings as to damages, the district court shall remand the action to the State court from which it had been removed for the determination of damages, unless the court finds that, for the convenience of parties and witnesses and in the interest of justice, the action should be retained for the determination of damages."],[0,"(3) Any remand under paragraph (2) shall not be effective until 60 days after the district court has issued an order determining liability and has certified its intention to remand the removed action for the determination of damages. An appeal with respect to the liability determination of the district court may be taken during that 60-day period to the court of appeals with appellate jurisdiction over the district court. In the event a party files such an appeal, the remand shall not be effective until the appeal has been finally disposed of. Once the remand has become effective, the liability determination shall not be subject to further review by appeal or otherwise."],[0,"(4) Any decision under this subsection concerning remand for the determination of damages shall not be reviewable by appeal or otherwise."],[0,"(5) An action removed under this subsection shall be deemed to be an action under section 1369 and an action in which jurisdiction is based on section 1369 of this title for purposes of this section and sections 1407, 1697, and 1785 of this title."],[0,"(6) Nothing in this subsection shall restrict the authority of the district court to transfer or dismiss an action on the ground of inconvenient forum."],[0,"(f) Derivative Removal Jurisdiction.—The court to which a civil action is removed under this section is not precluded from hearing and determining any claim in such civil action because the State court from which such civil action is removed did not have jurisdiction over that claim."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1441?type=usc&year=mostrecent&link-type=html"},"head":"§1441. Removal of civil actions","tname":"Judiciary and Judicial Procedure","by":{"0":"4","1":"16"}},{"t":"usc","label":"28 U.S.C. § 1446","url":"https://www.law.cornell.edu/uscode/text/28/1446","subs":["(b)(3)"],"stext":{"head":"§1446. Procedure for removal of civil actions","paras":[[0,"(a) Generally.—A defendant or defendants desiring to remove any civil action from a State court shall file in the district court of the United States for the district and division within which such action is pending a notice of removal signed pursuant to Rule 11 of the Federal Rules of Civil Procedure and containing a short and plain statement of the grounds for removal, together with a copy of all process, pleadings, and orders served upon such defendant or defendants in such action."],[0,"(b) Requirements; Generally.—(1) The notice of removal of a civil action or proceeding shall be filed within 30 days after the receipt by the defendant, through service or otherwise, of a copy of the initial pleading setting forth the claim for relief upon which such action or proceeding is based, or within 30 days after the service of summons upon the defendant if such initial pleading has then been filed in court and is not required to be served on the defendant, whichever period is shorter."],[0,"(2)(A) When a civil action is removed solely under section 1441(a), all defendants who have been properly joined and served must join in or consent to the removal of the action."],[0,"(B) Each defendant shall have 30 days after receipt by or service on that defendant of the initial pleading or summons described in paragraph (1) to file the notice of removal."],[0,"(C) If defendants are served at different times, and a later-served defendant files a notice of removal, any earlier-served defendant may consent to the removal even though that earlier-served defendant did not previously initiate or consent to removal."],[0,"(3) Except as provided in subsection (c), if the case stated by the initial pleading is not removable, a notice of removal may be filed within thirty days after receipt by the defendant, through service or otherwise, of a copy of an amended pleading, motion, order or other paper from which it may first be ascertained that the case is one which is or has become removable."],[0,"(c) Requirements; Removal Based on Diversity of Citizenship.—(1) A case may not be removed under subsection (b)(3) on the basis of jurisdiction conferred by section 1332 more than 1 year after commencement of the action, unless the district court finds that the plaintiff has acted in bad faith in order to prevent a defendant from removing the action."],[0,"(2) If removal of a civil action is sought on the basis of the jurisdiction conferred by section 1332(a), the sum demanded in good faith in the initial pleading shall be deemed to be the amount in controversy, except that—"],[1,"(A) the notice of removal may assert the amount in controversy if the initial pleading seeks—"],[2,"(i) nonmonetary relief; or"],[2,"(ii) a money judgment, but the State practice either does not permit demand for a specific sum or permits recovery of damages in excess of the amount demanded; and"],[1,"(B) removal of the action is proper on the basis of an amount in controversy asserted under subparagraph (A) if the district court finds, by the preponderance of the evidence, that the amount in controversy exceeds the amount specified in section 1332(a)."],[0,"(3)(A) If the case stated by the initial pleading is not removable solely because the amount in controversy does not exceed the amount specified in section 1332(a), information relating to the amount in controversy in the record of the State proceeding, or in responses to discovery, shall be treated as an \"other paper\" under subsection (b)(3)."],[0,"(B) If the notice of removal is filed more than 1 year after commencement of the action and the district court finds that the plaintiff deliberately failed to disclose the actual amount in controversy to prevent removal, that finding shall be deemed bad faith under paragraph (1)."],[0,"(d) Notice to Adverse Parties and State Court.—Promptly after the filing of such notice of removal of a civil action the defendant or defendants shall give written notice thereof to all adverse parties and shall file a copy of the notice with the clerk of such State court, which shall effect the removal and the State court shall proceed no further unless and until the case is remanded."],[0,"(e) Counterclaim in 337 Proceeding.—With respect to any counterclaim removed to a district court pursuant to section 337(c) of the Tariff Act of 1930, the district court shall resolve such counterclaim in the same manner as an original complaint under the Federal Rules of Civil Procedure, except that the payment of a filing fee shall not be required in such cases and the counterclaim shall relate back to the date of the original complaint in the proceeding before the International Trade Commission under section 337 of that Act."],[0,"(g) 1 Where the civil action or criminal prosecution that is removable under section 1442(a) is a proceeding in which a judicial order for testimony or documents is sought or issued or sought to be enforced, the 30-day requirement of subsection (b) of this section and paragraph (1) of section 1455(b) is satisfied if the person or entity desiring to remove the proceeding files the notice of removal not later than 30 days after receiving, through service, notice of any such proceeding."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1446?type=usc&year=mostrecent&link-type=html"},"head":"§1446. Procedure for removal of civil actions","tname":"Judiciary and Judicial Procedure","by":{"0":"4","1":"22"}},{"t":"usc","label":"28 U.S.C. § 1447","url":"https://www.law.cornell.edu/uscode/text/28/1447","subs":["(c)","(e)"],"stext":{"head":"§1447. Procedure after removal generally","paras":[[0,"(a) In any case removed from a State court, the district court may issue all necessary orders and process to bring before it all proper parties whether served by process issued by the State court or otherwise."],[0,"(b) It may require the removing party to file with its clerk copies of all records and proceedings in such State court or may cause the same to be brought before it by writ of certiorari issued to such State court."],[0,"(c) A motion to remand the case on the basis of any defect other than lack of subject matter jurisdiction must be made within 30 days after the filing of the notice of removal under section 1446(a). If at any time before final judgment it appears that the district court lacks subject matter jurisdiction, the case shall be remanded. An order remanding the case may require payment of just costs and any actual expenses, including attorney fees, incurred as a result of the removal. A certified copy of the order of remand shall be mailed by the clerk to the clerk of the State court. The State court may thereupon proceed with such case."],[0,"(d) An order remanding a case to the State court from which it was removed is not reviewable on appeal or otherwise, except that an order remanding a case to the State court from which it was removed pursuant to section 1442 or 1443 of this title shall be reviewable by appeal or otherwise."],[0,"(e) If after removal the plaintiff seeks to join additional defendants whose joinder would destroy subject matter jurisdiction, the court may deny joinder, or permit joinder and remand the action to the State court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1447?type=usc&year=mostrecent&link-type=html"},"head":"§1447. Procedure after removal generally","tname":"Judiciary and Judicial Procedure","by":{"0":"16","1":"11, 16-17, 19-22, 24, 30, 44, 44","2":"9, 13"}},{"t":"rule","label":"Fed. R. Civ. P. 21","url":"https://www.law.cornell.edu/rules/frcp/rule_21","by":{"0":"23","2":"16, 19"}},{"t":"rule","label":"Fed. R. Civ. P. 30","url":"https://www.law.cornell.edu/rules/frcp/rule_30","by":{"0":"28"}},{"t":"rule","label":"Fed. R. Civ. P. 34","url":"https://www.law.cornell.edu/rules/frcp/rule_34","by":{"0":"28"}},{"t":"case","label":"American Car & Foundry Co. v. Kettelhake","cite":"236 U.S. 311","y":1915,"id":"scdb/1914-219","sc":1,"sum":"Where there is a joint cause of action against defendants resident of plaintiff’s State and a non-resident defendant, in order to make the case removable as to the latter because of the dismissal as to the former, the discontinuance as to the resident.defendants must have been the voluntary act of the plaintiff and have so taken the resident defendants out of the case as to leave the controversy one wholly between …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"American Fire & Cas. Co. v. Finn","cite":"341 U.S. 6","y":1951,"id":"scdb/1950-055","sc":1,"op":1,"sum":"In a suit brought in a Texas court by a resident of that State to recover for a loss by fire, the complaint named as defendants two foreign insurance companies (one of which is the petitioner here) and a resident agent of the companies. The single wrong for which relief was sought was the failure to compensate for the loss, and the three defendants were joined because of uncertainty as to who was liable. After …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22","2":"8"}},{"t":"case","label":"Atlas Glob. Grp., L.P. v. Grupo Dataflux","cite":"312 F.3d 168","y":2002,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/312/168/","by":{"1":"33"}},{"t":"case","label":"Buck’s Stove & Range Co. v. American Fed’n of Labor","cite":"219 U.S. 581","y":1911,"id":"scdb/1910-184","sc":1,"sum":"No. 497. SAMUEL LOEB, PLAINTIFF IN ERROR, v. HENleY JENNINGS, CHIEF OF POLICE OF THE CITY OF ATLANTA. In error to the Supreme Court of the State of Georgia. Motion to dismiss or affirm submitted December 19, 1910. Decided January 3, 1911. Per Curiam. Judgment affirmed on the authority of Waters-Pierce Oil Company v. State of Texas, 212 U. S. 112, 118; Goodrich v. Ferris, 214 U. S. 79; Griffith v. Connecticut, 218 U. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Caribe Chem Distribs., Corp. v. Southern Agric. Insecticides, Inc.","cite":"96 F.4th 25","y":2024,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.4th/96/25/","by":{"1":"22"}},{"t":"case","label":"Caterpillar Inc. v. Williams","cite":"482 U.S. 386","y":1987,"id":"1986/86-526","sc":1,"sum":"Respondents' state-law complaint for breach of the individual employment contracts is not removable to Federal District Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Catlin v. United States","cite":"324 U.S. 229","y":1945,"id":"scdb/1944-071","sc":1,"sum":"1. In a proceeding instituted by a petition in the District Court for the condemnation of land under the War Purposes Act of 1917, a \"judgment\" entered upon a declaration of taking filed pursuant to the Declaration of Taking Act of 1931, and a subsequent order denying the landowner's motion to vacate the judgment and to dismiss the petition, held not \"final decisions\" under § 128 of the Judicial Code and therefore …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Chicago, R.I. & P. Ry. Co. v. Schwyhart","cite":"227 U.S. 184","y":1913,"id":"scdb/1912-083","sc":1,"sum":"Whether there was a joint liability of defendants sued jointly for negligence is a matter of state law and this court will not go behind the decision of the highest court of the State to which the question can go. Southern Railway Co. v. Miller, 217 U. S. 209.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"16, 45"}},{"t":"case","label":"Chicago, R.I. & P. Ry. Co. v. Whiteaker","cite":"239 U.S. 421","y":1915,"id":"scdb/1915-005","sc":1,"sum":". In the absence of bad faith, the motive of the plaintiff in making defendants parties who are jointly liable does not affect the right to remove the case.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Cohen v. Beneficial Indus. Loan Corp.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"sum":"1. Under 28 U. S. C. § 1291, appeal may be. taken from an order of a Federal District Court denying a corporation's motion that the plaintiff in a stockholder's derivative action be required, pursuant to a state statute, to give security for reasonable expenses of the defendants, in connection with the action.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Deposit Guar. Nat’l Bank v. Roper","cite":"445 U.S. 326","y":1980,"id":"1979/78-904","sc":1,"sum":"Neither petitioner's tender nor the District Court's entry of judgment in favor of respondents over their objections mooted their private case or controversy, and their individual interest in the litigation-as distinguished from whatever may be their representative responsibilities to the putative class-is sufficient to permit their appeal of the adverse certification ruling.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Dupree v. Younger","cite":"598 U.S. 729","y":2023,"id":"2022/22-210","sc":1,"op":1,"sum":"A post-trial motion under Federal Rule of Civil Procedure 50 is not required to preserve for appellate review a purely legal issue resolved at summary judgment.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"21"}},{"t":"case","label":"Exxon Mobil Corp. v. Allapattah Servs., Inc.","cite":"545 U.S. 546","y":2005,"id":"2004/04-70","sc":1,"sum":"The Court ruled that as long one plaintiff meets the amount-in-controversy requirement for federal jurisdiction, Section 1367 authorizes federal courts to exercise supplemental jurisdiction over related claims even if they do not meet the requirement.","sumSrc":"Oyez","by":{"1":"4, 14-15, 17, 28"}},{"t":"case","label":"F.F.P. Operating Partners, L.P. v. Duenez","cite":"237 S.W.3d 680","y":2007,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.3d/237/680/","by":{"1":"46"}},{"t":"case","label":"Gelboim v. Bank of Am. Corp.","cite":"574 U.S. 405","y":2015,"id":"2014/13-1174","sc":1,"sum":"The Court ruled that a dismissed claim is immediately appealable if the claim is part of a consolidated action and no final order has been issued concerning all claims in the action.","sumSrc":"Oyez","by":{"1":"21, 33"}},{"t":"case","label":"Great N. Ry. Co. v. Alexander","cite":"246 U.S. 276","y":1918,"id":"scdb/1917-082","sc":1,"op":2,"sum":"A case arising under the Federal Employers’ Liability Act between citizens of different States is not removable from a state to a federal District Court on either ground.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"Greenlaw v. United States","cite":"554 U.S. 237","y":2008,"id":"2007/07-330","sc":1,"sum":"The Court stated that the Eighth Circuit could not order the district court to increase Greenlaw's sentence without a request from the government to do so. The Court pointed to several of its precedents for the rule that a remedy in favor the appellee, in this case the government, can only be justified if the appellee brings a cross-appeal.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"Healy v. Ratta","cite":"292 U.S. 263","y":1934,"id":"scdb/1933-157","sc":1,"sum":"(1) That the matter in controversy did not embrace the right to restrain enforcement of the law by other officers in other places in the State, and that the collateral effect of the decree, by virtue of stare decisis, upon other and distinct controversies with other officers, could not be considered in ascertaining whether the jurisdictional amount was involved, even though their decision might turn on the same …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Illinois Cent. R.R. Co. v. Sheegog","cite":"215 U.S. 308","y":1909,"id":"scdb/1909-035","sc":1,"op":4,"sum":"Where the joinder of the resident and the non-resident defendants prevents removal to the Federal court, the fact that on the trial the jury finds against the non-resident defendant only has no bearing on the question of removal if the joinder was not fraudulent.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Italian Cowboy Partners, Ltd. v. Prudential Ins. Co.","cite":"341 S.W.3d 323","y":2011,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.3d/341/323/","by":{"1":"10"}},{"t":"case","label":"Izumi Seimitsu Kogyo Kabushiki Kaisha v. U.S. Philips Corp.","cite":"510 U.S. 27","y":1993,"id":"1993/92-1123","sc":1,"sum":"Petitioner Izumi Seimitsu Kogyo Kabushiki Kaisha was a party at the first trial in an action brought against it and respondent Windmere Corporation by respondent U. S. Philips Corporation, but was not a party to the second trial, in which Windmere prevailed. While the judgments from the second trial were on appeal, respondents reached a settlement and filed a joint motion to vacate the District Court's judgments. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"38"}},{"t":"case","label":"Junk v. Terminix Int’l Co.","cite":"628 F.3d 439","y":2010,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/628/439/","op":1,"by":{"1":"36"}},{"t":"case","label":"Kokkonen v. Guardian Life Ins. Co. of Am.","cite":"511 U.S. 375","y":1994,"id":"1993/93-263","sc":1,"op":2,"sum":"A federal district court, possessing only that power authorized by Constitution and statute, lacks jurisdiction over a claim for breach of a contract, part of the consideration for which was dismissal of an earlier federal suit. No federal statute makes that connection (if it constitutionally could) the basis for federal-court jurisdiction over the contract dispute. Moreover, the doctrine of ancillary jurisdiction …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14, 36"}},{"t":"case","label":"Kramer v. Lewisville Mem’l Hosp.","cite":"858 S.W.2d 397","y":1993,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.2d/858/397/","by":{"1":"46"}},{"t":"case","label":"Lexecon Inc. v. Milberg Weiss Bershad Hynes & Lerach","cite":"523 U.S. 26","y":1998,"id":"1997/96-1482","sc":1,"op":1,"ar":4,"sum":"The Court held that a district court conducting pretrial proceedings pursuant to section 1407(a) has no authority to invoke section 1404(a) to assign a transferred case to itself for trial.","sumSrc":"Oyez","by":{"1":"19, 22, 24, 29-31, 35, 37","2":"8, 9"}},{"t":"case","label":"Lincoln Prop. Co. v. Roche","cite":"546 U.S. 81","y":2005,"id":"2005/04-712","sc":1,"op":1,"sum":"The Court held that Lincoln did not need to negate the existence of a potential defendant whose presence in the action would destroy diversity. To remove the suit to federal court, Lincoln only needed to show complete diversity between all named plaintiffs and all named defendants.","sumSrc":"Oyez","by":{"1":"18, 44"}},{"t":"case","label":"Louisville & N.R.R. Co. v. Mottley","cite":"211 U.S. 149","y":1908,"id":"scdb/1908-012","sc":1,"sum":"The jurisdiction of the Circuit Court is défined and limited by statute; and, even if not questioned by either party, this court will, of its own motion, see to it that such jurisdiction is not exceeded.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"3"}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith Inc. v. Manning","cite":"578 U.S. 374","y":2016,"id":"2015/14-1132","sc":1,"sum":"The Court determined that the Securities Exchange Act of 1934 creates the same test for establishing federal jurisdiction as the general test for whether a federal court has jurisdiction: Whether the case “arises under” federal law.","sumSrc":"Oyez","by":{"1":"17, 36, 48"}},{"t":"case","label":"OBB Personenverkehr AG v. Sachs","cite":"577 U.S. 27","y":2015,"id":"2015/13-1067","sc":1,"sum":"The Court held that the commercial activity exception to the Foreign Sovereign Immunity Act only applies when the suit is based upon activity that took place in the United States, and it was not sufficient to establish a single element of the claim in question.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"Pennington v. Singleton","cite":"606 S.W.2d 682","y":1980,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.2d/606/682/","by":{"1":"10"}},{"t":"case","label":"Poulos v. Naas Foods, Inc.","cite":"959 F.2d 69","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/959/69/","by":{"1":"22"}},{"t":"case","label":"Powers v. Chesapeake & O. Ry. Co.","cite":"169 U.S. 92","y":1898,"id":"scdb/1897-061","sc":1,"sum":"A judgment of tlie Circuit Court of the United States, against a party contending that that court has no jurisdiction because the case has not been duly removed from a state court, may be reviewed as to the question of jurisdiction by this court upon writ of error directly to that court under the act of March 3, 1891, c. 517, § 5.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"Quackenbush v. Allstate Ins. Co.","cite":"517 U.S. 706","y":1996,"id":"1995/95-244","sc":1,"op":1,"sum":"The Court held that an abstention-based remand order is appealable because the \"remand order here falls within that narrow class of collateral orders that are immediately appealable.\" Further, the Court held that the \"federal courts have the power to dismiss or remand cases based on abstention principles only where the relief sought is equitable or otherwise discretionary,\" and because \"this was a damages action, the District Court's remand order was an unwarranted application of the Burford doctrine.\" Justices Antonin Scalia and Anthony M. Kennedy wrote concurring opinions.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Rivers v. Guerrero","cite":"605 U.S. 443","y":2025,"id":"2024/23-1345","sc":1,"sum":"Once a district court enters its judgment with respect to a first-filed habeas petition, see 28 U. S. C. §2254, a second-in-time filing qualifies as a “second or successive application” under the Antiterrorism and Effective Death Penalty Act of 1996 properly subject to the requirements of §2244(b).","sumSrc":"Holding (supremecourt.gov)","by":{"1":"40"}},{"t":"case","label":"Ruhrgas AG v. Marathon Oil Co.","cite":"526 U.S. 574","y":1999,"id":"1998/98-470","sc":1,"sum":"The Court held that in cases removed from a state court to federal court there is \"no unyielding jurisdictional hierarchy requiring the federal court to adjudicate subject-matter jurisdiction before considering a challenge to personal jurisdiction.\" Customarily, however, a federal court would first resolve doubts about its jurisdiction over the subject matter.","sumSrc":"Oyez","by":{"1":"17, 37"}},{"t":"case","label":"Stanley v. City of Sanford","cite":"145 S. Ct. 2058","y":2025,"id":"2024/23-997","sc":1,"sum":"To prevail under 42 U. S. C. §12112(a), a plaintiff must plead and prove that she held or desired a job, and could perform its essential functions with or without reasonable accommodation, at the time of an employer’s alleged act of disability-based discrimination; the judgment of the Eleventh Circuit is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"39"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"op":2,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"1":"14, 19, 48"}},{"t":"case","label":"Swint v. Chambers Cnty. Comm’n","cite":"514 U.S. 35","y":1995,"id":"1994/93-1636","sc":1,"sum":"The Eleventh Circuit lacked jurisdiction to rule on the county commission's liability at this interlocutory stage of the litigation and, accordingly, should have dismissed the commission's appeal.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Syngenta Crop Prot., Inc. v. Henson","cite":"537 U.S. 28","y":2002,"id":"2002/01-757","sc":1,"sum":"The Court held that the All Writs Act does not provide removal jurisdiction.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"United States v. Sineneng-Smith","cite":"590 U.S. 371","y":2020,"id":"2019/19-67","sc":1,"sum":"The Court held that the Ninth Circuit’s decision below was an abuse of discretion because it considered and ruled on an issue not raised by the parties.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"Waetzig v. Halliburton Energy Servs., Inc.","cite":"145 S. Ct. 690","y":2025,"id":"2024/23-971","sc":1,"sum":"A case voluntarily dismissed without prejudice under Federal Rule of Civil Procedure 41(a) counts as a “final proceeding” under Rule 60(b).","sumSrc":"Holding (supremecourt.gov)","by":{"1":"41"}},{"t":"case","label":"Whitcomb v. Smithson","cite":"175 U.S. 635","y":1900,"id":"scdb/1899-095","sc":1,"sum":"On the facts, as stated below, it is held that the action of the Circuit Court in remanding the cause after its removal on the first application is not open to revision on this writ of error; and that, as the state court did not err in denj'ing the second application, the motion to affirm must be sustained, as the question of the effect of that remanding order gave color for the motion to dismiss.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"22-23"}},{"t":"case","label":"Wilkinson v. Shackelford","cite":"478 F.3d 957","y":2007,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/478/957/","by":{"1":"36"}},{"t":"case","label":"Wilson v. Republic Iron & Steel Co.","cite":"257 U.S. 92","y":1921,"id":"scdb/1921-013","sc":1,"sum":"1. Whether a District Court into which a case has been removed from a state court may retain the case and proceed to its adjudication; or must remand it to the court whence it came, is a jurisdictional question a decision of which sustaining the jurisdiction may be reviewed here by direct writ of error, under Jud. Code, § 238, after final judgment.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"sum":"The Fifth Amendment's Takings Clause generally requires just compensation where the government authorizes a physical occupation of property. But where the government merely regulates the property's use, compensation is required only if considerations such as the regulation's purpose or the extent to which it deprives the owner of the property's economic use suggests that the regulation has unfairly singled out the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"38-39"}},{"t":"usc","label":"28 U.S.C. § 1407","url":"https://www.law.cornell.edu/uscode/text/28/1407","subs":["(a)"],"by":{"1":"29-30"}},{"t":"case","label":"Bolden v. Brooks","cite":"138 F. App’x 601","y":2005,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/138/601/","by":{"2":"4"}},{"t":"case","label":"Bowen Eng'g Corp. v. Pac. Indem. Co.","cite":"2014 WL 6908747","y":2014,"court":"D. Kan. Dec. 8","by":{"2":"5"}},{"t":"case","label":"de Fernandez v. CMA CGM S.A.","cite":"2024 WL 3580949","y":2024,"court":"S.D. Fla. July 30","by":{"2":"5"}},{"t":"case","label":"Finn v. Am. Fire & Cas. Co.","cite":"207 F.2d 113","y":1953,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/207/113/","by":{"2":"8"}},{"t":"case","label":"Firestone Tire & Rubber Co. v. Risjord","cite":"449 U.S. 368","y":1981,"id":"1980/79-1420","sc":1,"sum":"Respondent is lead counsel for the plaintiffs in four consolidated productliability suits in Federal District Court against petitioner and other manufacturers. Petitioner moved to disqualify respondent from further representation of the plaintiffs because of an alleged conflict of interest arising from the fact that petitioner's liability insurer was also an occasional client of respondent's law firm. Petitioner …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"3"}},{"t":"case","label":"Iloominate Media, Inc. v. CAIR Fla., Inc.","cite":"841 F. App’x 132","y":2020,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/841/132/","by":{"2":"4"}},{"t":"case","label":"Kitchen v. Heyns","cite":"802 F.3d 873","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/802/873/","by":{"2":"5"}},{"t":"case","label":"Marcello v. Maine","cite":"2006 WL 3804891","y":2006,"court":"D. Me. Dec. 22","by":{"2":"5"}},{"t":"case","label":"Publicker Indus., Inc. v. Roman Ceramics Corp.","cite":"603 F.2d 1065","y":1979,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/603/1065/","op":1,"by":{"2":"19"}},{"t":"case","label":"Tayal v. Bank of N.Y. Mellon","cite":"2022 WL 563240","y":2022,"court":"4th Cir. Feb. 24","by":{"2":"4"}},{"t":"case","label":"Tungsten Parts Wyo., Inc. v. Omanoff","cite":"2023 WL 2630417","y":2023,"court":"D. Wyo. Feb. 27","by":{"2":"5"}},{"t":"case","label":"Wagle v. Mich. Dep’t of Corr.","cite":"2012 WL 4795638","y":2012,"court":"E.D. Mich. Oct. 9","by":{"2":"5"}},{"t":"case","label":"Petition, Caterpillar Inc. v. Lewis","cite":"1996 WL 33413834","y":1996,"court":"U.S. filed Feb. 8","by":{"2":"12"}}]};